import{_ as o,H as a,f as t,i as r}from"./chunks/framework.CBmkDW73.js";const g=JSON.parse('{"title":"ベストプラクティス","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/best-practices.md","filePath":"ja/guide/best-practices.md"}'),n={name:"ja/guide/best-practices.md"};function s(i,e,d,c,l,p){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="ベストプラクティス" tabindex="-1">ベストプラクティス <a class="header-anchor" href="#ベストプラクティス" aria-label="Permalink to &quot;ベストプラクティス&quot;">​</a></h1><h2 id="仕様" tabindex="-1">仕様 <a class="header-anchor" href="#仕様" aria-label="Permalink to &quot;仕様&quot;">​</a></h2><p><strong>宣言的に書く、物語的にではなく。</strong> <code>contract:</code>、<code>invariant:</code>、<code>test:</code>、<code>failure:</code> のようなセクションを使う。番号付きステップや散文は使わない。エージェントは速く読み、精確な宣言に従う。</p><p><strong>実装に影響する決定だけを閉じる。</strong> <code>plan</code> に引き渡す前に解決すること：契約、データ形状、失敗モード、テスト基準。哲学的な議論や「あれば良い」機能は <code>deferred</code> または <code>Working notes</code> に残す。</p><p><strong>コードはパスで参照し、貼り付けない。</strong> 仕様は何を作るかについての決定であり、どう作るかのウォークスルーではない。</p><h2 id="計画" tabindex="-1">計画 <a class="header-anchor" href="#計画" aria-label="Permalink to &quot;計画&quot;">​</a></h2><p><strong>タスクは30〜60分。</strong> エージェントが推論できるほど原子的に。大きすぎると可視性を失い、小さすぎるとオーバーヘッドが勢いを殺す。</p><p><strong>受け入れ条件は実行可能。</strong> 各タスクの受け入れ条件はCI/人間が検証できるものでなければならない：テスト名、コマンド、またはスクリプト。曖昧にせず、理想論にしない。</p><p><strong><code>[parallel]</code> は本当に独立している場合のみマーク。</strong> 共有状態、エラー処理、または閉じていない契約があるタスクは並行ではない。過剰マークは壊れたマージにつながる。</p><h2 id="gitワークフロー" tabindex="-1">Gitワークフロー <a class="header-anchor" href="#gitワークフロー" aria-label="Permalink to &quot;Gitワークフロー&quot;">​</a></h2><p><strong>RED-GREEN-refactorサイクルごとに一回コミット。</strong> 思考を履歴に残す。後でデバッグするときに役立つ。</p><p><strong>各サイクル後にドキュメントを同期。</strong> コミット直前。待つと何を変えたか、なぜ変えたかを忘れる。</p><p><strong>説明的なブランチ名を使う。</strong> <code>feature1</code> ではなく <code>feat/oauth-github</code>。複数のworktreeがある時にナビゲートしやすい。</p><h2 id="大規模プロジェクト" tabindex="-1">大規模プロジェクト <a class="header-anchor" href="#大規模プロジェクト" aria-label="Permalink to &quot;大規模プロジェクト&quot;">​</a></h2><p><strong>マイルストーンが≥3つある場合はロードマップを使う。</strong> 最初から全部計画しようとしない。現在のものだけ <code>plan</code> して、学習しながらスタブを更新する。</p><p><strong>現在のマイルストーンを明確にマーク。</strong> M1に <code>← 今詳細に計画</code> で意図を示す。ship後、M2を計画する前にマーカーを移動する。</p><p><strong>M1後にマイルストーンを修正することを想定。</strong> 最初のマイルストーンが残りのコストを教えてくれる。それが要点だ。</p><h2 id="デバッグ" tabindex="-1">デバッグ <a class="header-anchor" href="#デバッグ" aria-label="Permalink to &quot;デバッグ&quot;">​</a></h2><p><strong>まず隔離し、次に仮説を立てる。</strong> 最小の再現まで絞り込む。症状が消えるまでコードを削る。その後「なぜ」を問う。</p><p><strong>一度に一つの変数だけ変える。</strong> 並行仮説は魅力的だが、どの変更が修正したかわかりにくくなる。</p><h2 id="テスト" tabindex="-1">テスト <a class="header-anchor" href="#テスト" aria-label="Permalink to &quot;テスト&quot;">​</a></h2><p><strong>実装ではなく契約をテストする。</strong> 契約が「成功時に200を返す」と言うなら、それをテストする。「X関数を呼ぶ」や「データベースYから読む」ではない。</p><p><strong>内部のモックなし。</strong> 外部境界をモック：HTTP、DB、ファイルシステム。自分のコードをモックするのは実際のバージョンが遅いか非確定的な場合のみ。</p><h2 id="いつ諦めるか" tabindex="-1">いつ諦めるか <a class="header-anchor" href="#いつ諦めるか" aria-label="Permalink to &quot;いつ諦めるか&quot;">​</a></h2><p><strong>前提が本質的に変わったら、止めて再探索する。</strong> 解こうとしている問題がもはや問題でないなら、無理に進めない。発見ノートに試みと理由と学びをマークする。</p><p><strong>マイルストーンのゴールが≥50%ずれたら、設計に戻る。</strong> 計画を延長しない。新しい方向を認め、再開する。</p><h2 id="仕様レビューの統合評価-spec-review-synthesis" tabindex="-1">仕様レビューの統合評価 (Spec Review Synthesis) <a class="header-anchor" href="#仕様レビューの統合評価-spec-review-synthesis" aria-label="Permalink to &quot;仕様レビューの統合評価 (Spec Review Synthesis)&quot;">​</a></h2><p><strong>レビュアーは助言を行い、Coordinator が裁决を下します。</strong> 仕様レビュアーは独立したサブエージェントとして専用の役割で動作します。主エージェント（Coordinator）は指摘事項を批判的に評価し、矛盾の解決、漏れの特定を行い、一度の変更で仕様書を修正します。</p><h2 id="モデル階層マッピング-model-tier-mapping" tabindex="-1">モデル階層マッピング (Model Tier Mapping) <a class="header-anchor" href="#モデル階層マッピング-model-tier-mapping" aria-label="Permalink to &quot;モデル階層マッピング (Model Tier Mapping)&quot;">​</a></h2><p><strong>タスクのリスクに応じてモデルの能力をマッチングさせます。</strong> 機械的な修正や Lint チェックには <code>fast</code>、単一コンポーネントの実装には <code>balanced</code>、核心プロトコルや安全レビュー、複雑な状態マシンには <code>strongest</code> を使用します。<code>.praxis/model-tiers.yaml</code> で設定します。</p><h2 id="マルチモジュール調整-multi-module-coordination" tabindex="-1">マルチモジュール調整 (Multi-Module Coordination) <a class="header-anchor" href="#マルチモジュール調整-multi-module-coordination" aria-label="Permalink to &quot;マルチモジュール調整 (Multi-Module Coordination)&quot;">​</a></h2><p><strong>Coordinator リポジトリを1つ明示的に指定します。</strong> Coordinator が change-set ID、モジュール横断仕様、ワークスペース計画を所有します。各モジュール仕様で共有契約を重複記述せず、Coordinator 仕様を直接参照します。コミットは依存関係順に行い、Coordinator が最後にコミットします。</p><h2 id="ドキュメント同期" tabindex="-1">ドキュメント同期 <a class="header-anchor" href="#ドキュメント同期" aria-label="Permalink to &quot;ドキュメント同期&quot;">​</a></h2><p><strong>リビングドキュメントは事実、ステージングドキュメントは下書きです。</strong> <code>ship</code> の後、仕様はリビングドキュメントに移動します。コード内のテストやコメントは常に最新を維持します。</p><p><strong>README は最初の仕様書です。</strong> コードと一致しない場合、PR のレビューは不合格となります。同じルールがすべての公開契約に適用される。</p>',35)])])}const u=o(n,[["render",s]]);export{g as __pageData,u as default};
